graphql.query:
query {
  apiVersion
  sampleCount
  skipRate
  snapshot {
    generatedAt
    totalSamples
    validatorsSeen
    observed
    skipped
    skipRate
    slotTime { count min p50 p90 p99 max mean }
    voteLatency { count min p50 p90 p99 max mean }
  }
}

query Worst($limit: Int!) {
  worstValidators(limit: $limit) {
    validator
    slotsLed
    slotsSkipped
    skipRate
    slotTime { p50 p99 }
    voteLatency { p50 p99 }
  }
}

query Report($validator: String!) {
  validatorReport(validator: $validator) {
    validator
    slotsLed
    slotsSkipped
    skipRate
    slotTime { count min p50 p90 p99 max mean }
    voteLatency { count min p50 p90 p99 max mean }
  }
}

query Epoch($epoch: Int!) {
  epochSummary(epoch: $epoch) {
    epoch
    samples
    skipRate
    slotTimeP50
    slotTimeP99
    voteLatencyP50
    voteLatencyP99
  }
}
